export const impostorTrialStorageKey="timelessMemoryImpostorTrials:v1";const limit=2;export function createImpostorTrial({getStorage:t}){let r=!1;function e(){if(r)return null;try{const r=t().getItem(impostorTrialStorageKey);if(null===r)return 2;if(!/^[0-2]$/.test(r))return 0;const e=Number(r);return Number.isInteger(e)&&e>=0&&e<=2?2-e:0}catch{return r=!0,null}}return{remaining:e,consume(){const n=e();if(null===n||n<=0)return!1;try{return t().setItem(impostorTrialStorageKey,String(2-n+1)),!0}catch{return r=!0,!1}}}}
